function blob(bytes){return crypto.createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex');}
async function obtain(row){
const sha=row.file_revision_sha,key=row.repository+':'+sha;
if(!cache.has(key))cache.set(key,(async()=>{const url='https://api.github.com/repos/BestNameYet/'+row.repository+'/git/blobs/'+sha;
const res=await fetch(url,{headers:{Authorization:'Bearer '+process.env.GH_TOKEN,Accept:'application/vnd.github+json'}});
